                                                </button>
                                                <button
                                                    type="button"
                                                    onClick={() => handleOpenCreateModuleModal(department)}
                                                    className="inline-flex items-center gap-1 rounded-lg border border-red-200 px-2.5 py-1.5 text-xs font-semibold text-red-700 transition hover:bg-red-50"
