                        <div>
                            <label className="mb-1 block text-xs font-semibold text-gray-700">Açıklama</label>
                            <textarea
                                value={moduleForm.description}
                                onChange={(event) => setModuleForm((prev) => ({ ...prev, description: event.target.value }))}
