                                }}
                                className={`h-10 w-full rounded-lg px-3 text-sm outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 ${
                                    isTeamLeaderError ? 'border border-red-500' : 'border border-gray-300'
