                            >
                                Iptal
                            </button>
                            <button
                                type="submit"
                                disabled={isModuleSubmitting}
                                className="h-9 rounded-lg bg-red-600 px-4 text-sm font-semibold text-white transition hover:bg-red-700 disabled:cursor-not-allowed disabled:bg-gray-300"
                            >
