                  <th className="px-2 py-2 font-semibold">Gecikme</th>
                  <th className="px-2 py-2 font-semibold">Kalan</th>
                </tr>
              </thead>
              <tbody>
                {filteredOverdueInvoices.length === 0 ? (
                  <tr>
